import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const AddAttendance = () => {
  const [attendance, setAttendance] = useState({
    residentId: '',
    date: new Date().toISOString().split('T')[0],
    status: 'Present',
  });
  const [residents, setResidents] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetchResidents();
  }, []);

  const fetchResidents = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/residents');
      setResidents(response.data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleChange = (e) => {
    setAttendance({ ...attendance, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5000/api/attendance', attendance);
      navigate('/attendance');
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>Add Attendance</h2>
      <select name="residentId" value={attendance.residentId} onChange={handleChange} required>
        <option value="">Select Resident</option>
        {residents.map((resident) => (
          <option key={resident._id} value={resident._id}>
            {resident.name}
          </option>
        ))}
      </select>
      <input
        type="date"
        name="date"
        value={attendance.date}
        onChange={handleChange}
        required
      />
      <select name="status" value={attendance.status} onChange={handleChange}>
        <option value="Present">Present</option>
        <option value="Absent">Absent</option>
      </select>
      <button type="submit" className="submit-btn">
        Add Attendance
      </button>
    </form>
  );
};

export default AddAttendance;
